/* the selection as its rings and nothing else, the card's cut. Each ring is
   a toggle at the tap floor; out of the run it steps back rather than going,
   so a second tap brings it back. */
.st-rings{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0 0}
.st-rq{display:inline-flex;align-items:center;justify-content:center;min-width:var(--tap);min-height:var(--tap);
 padding:0;border:0;border-radius:999px;background:transparent;cursor:pointer;
 transition:opacity var(--t-element) var(--ease-out)}
.st-rq[aria-pressed="false"]{opacity:.35}
.st-rq:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.st-rlfoot{margin-top:auto;padding-top:10px}
/* the card's two fields, .rel-field, set to the column's left edge */
.rel-fields.st-fields{justify-content:flex-start;margin:0}
.st-go{width:100%;margin-top:12px;min-height:52px;border-radius:var(--r-s);border:0;cursor:pointer;
 font-family:var(--sans);font-size:16px;font-weight:600;background:var(--glow);color:var(--on-accent);
 transition:filter var(--t-micro) var(--ease-out)}
.st-go:hover{filter:brightness(1.08)}
.st-go:disabled{opacity:.4;cursor:default}
/* the negated word, struck, with the negator inside the mark. See stMarks. */
.st-f.neg{background:none;box-shadow:none;color:var(--dim);text-decoration:line-through;
