/* ============================================================
   ANALYTICS
   ============================================================ */
.ab-hero{display:flex;gap:20px;align-items:center;padding:18px 22px;border-radius:var(--r);
 background:var(--panel-2);border:1px solid var(--edge);margin-bottom:12px;flex-wrap:wrap}
