/* ============================================================
   DRILL
   ============================================================ */
.rd-card{border:1px solid rgba(223,204,126,.34);border-radius:var(--r);padding:16px 18px;
/* THE BACK CONTROL. Sticky at the top of the drill, because the reason it
   exists is that the old one was at the bottom. It names where it goes, since
   "close" says what happens to the panel and not what happens to the person. */
.rd-top{position:sticky;top:0;z-index:2;margin:-2px -2px 10px;padding:2px 2px 8px;
/* THE COMPASS READING, IN THE RAIL. Two wrappers that went in with the move
   and carried no rule, which the design gate refuses by name: a class with no
   CSS is either dead markup or a rule somebody forgot. These space the three
   parts the compass sends over, and nothing else. */
.cone-read{margin-bottom:4px}
.cone-rec{margin:16px 0 4px;padding-top:14px;border-top:1px solid var(--edge)}
 background:linear-gradient(var(--panel) 72%,transparent)}
.rd-back{display:inline-flex;align-items:center;gap:6px;min-height:var(--tap);
 padding:6px 12px 6px 7px;margin-left:-7px;background:none;border:0;
 border-radius:999px;color:var(--dim);font:inherit;font-size:13px;cursor:pointer;
 transition:color var(--t-micro) var(--ease-out)}
.rd-back:hover{color:var(--ink)}
.rd-back:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.rd-back svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.9;
 stroke-linecap:round;stroke-linejoin:round}
 background:rgba(223,204,126,.06);margin:12px 0}
.ad-nm{font-size:21px;font-weight:600;margin:5px 0 3px;letter-spacing:0}
.ad-sub{font-size:13px;color:var(--dim);margin-bottom:11px}
.ad-rows{display:flex;flex-direction:column;gap:2px;margin-top:6px}
.ad-r{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;
 text-align:left;width:100%;border:0;background:transparent;cursor:pointer;min-height:var(--tap);font-family:var(--sans);
 font-size:13.5px;color:var(--mid);padding:5px 6px;border-radius:var(--r-xs)}
.ad-r:hover{background:var(--panel-2)}
.ad-r span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--ink)}
.ad-r em{font-style:normal;font-size:12px;color:var(--heart)}
.ad-r b{font-weight:500;color:var(--gold);font-family:var(--num);font-variant-numeric:tabular-nums}
.ad-q{font-size:14px;line-height:1.7;color:var(--dim);font-style:italic;
 border-left:3px solid var(--gold);padding-left:12px;margin:8px 0;font-weight:300}

/* ============================================================
   DIAGNOSTIC 21 x 3
   ============================================================ */
/* The left rail variant is gone with the rail. The questions are their own
   surface now, ruled, and these five rules were overriding the new grid. */
/* the identity block. it opens the intake, because the birth moment is the
   only input the person cannot answer from memory of how they behave. */
.iq-who{padding:15px 17px;border-radius:var(--r-s);background:var(--panel-2);
 border:1px solid var(--edge);margin-bottom:12px}
.iq-why{font-size:13px;line-height:1.7;color:var(--mid);margin:9px 0 14px;max-width:74ch}
/* THE ROLLED UP IDENTITY. One line and an edit control, because the form has
   done its job and a birth moment does not change. */
.iq-sealed{display:flex;align-items:center;gap:16px;padding:13px 15px;margin-bottom:12px;
 border-radius:var(--r-s);background:var(--panel-2);border:1px solid var(--edge)}
body.punch .iq-sealed{border-color:transparent}
.iq-sl-l{flex:1 1 auto;min-width:0}
.iq-sl-nm{font-size:17px;font-weight:400;color:var(--ink);margin-top:5px;letter-spacing:.01em}
.iq-sl-bt{font-size:12.5px;color:var(--dim);margin-top:3px}
.iq-sl-gap{font-size:12.5px;color:var(--sacral);margin-top:4px}
.iq-seal-r{display:flex;align-items:center;gap:12px;flex-wrap:wrap;
 margin-top:14px;padding-top:13px;border-top:1px solid var(--edge)}
body.punch .iq-seal-r{border-top-color:var(--panel-2)}
.iq-seal-n{font-size:12.5px;color:var(--dim)}
.iq-seal-r .btn[disabled]{opacity:.45;cursor:not-allowed}
.iq-seed{margin-top:13px;padding-top:13px;border-top:1px solid var(--edge)}
body.punch .iq-seed{border-top-color:var(--panel-2)}
.iq-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(168px,1fr));gap:10px}
.iq-f{display:flex;flex-direction:column;gap:6px;min-width:0}
.iq-f label{font-size:11px;color:var(--dim);font-weight:600}
/* every select and every checkbox on this surface, not only the ones that
   happen to sit inside a .iq-f. #iqprof and #wtype carry no class at all and
   were the two the gate kept finding. */
.iq select,.iq input[type=text],.iq input[type=date],.iq input[type=time],
.iq-f input,.iq-f select{background:var(--sunk);border:1px solid var(--edge);color:var(--ink);
 border-radius:var(--r-xs);padding:0 10px;min-height:var(--tap);font-family:var(--sans);font-size:13.5px;width:100%;box-sizing:border-box}
.iq-f input:focus,.iq-f select:focus,.iq select:focus{border-color:var(--accent)}
.iq select{width:auto;min-width:0;max-width:100%}
.iq-ck{display:flex;align-items:center;gap:10px;min-height:var(--tap);font-size:12.5px;color:var(--dim)}
/* A CHECKBOX IS A CONTROL. An 18 pixel box is a thumb missing it. The box
   itself stays 18, because a 44 pixel checkbox looks like a bug, and the
   target is the whole label, which is already at the floor. The input carries
   the padding so its own hit area reaches the floor with it. */
.iq-ck input{width:18px;height:18px;accent-color:var(--accent);
 padding:13px;margin:-13px;background-clip:content-box;flex:0 0 auto}
.iq-ck{cursor:pointer}
body.punch .iq-who{border-color:transparent}
body.punch .iq-f input,body.punch .iq-f select{border-color:transparent}
.iq-top{display:flex;gap:18px;align-items:center;flex-wrap:wrap;padding:15px 17px;
 border-radius:var(--r-s);background:var(--panel-2);border:1px solid var(--edge)}
.iq-cq b{display:block;font-family:var(--num);font-size:38px;font-weight:400;line-height:1;
 color:var(--gold);font-variant-numeric:tabular-nums}
.iq-cq span{font-size:11px;font-weight:600;color:var(--dim);display:block;margin-top:4px}
.iq-pr{flex:1 1 200px}
.iq-bar{height:8px;background:var(--sunk);border-radius:4px;overflow:hidden}
.iq-bar i{display:block;height:100%;background:var(--gold);border-radius:4px;transition: width var(--t-context) var(--ease-out)}
.iq-pl{font-size:13px;color:var(--dim);margin-top:8px}
.iq-pl b{color:var(--ink);font-weight:500}
.iq-act{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
#iqprof{background:var(--panel-2);color:var(--ink);border:1px solid var(--edge);
 border-radius:var(--r-xs);padding:8px 10px;font-family:var(--sans);font-size:14px;max-width:150px}
#iqprof option{background:var(--panel);color:var(--ink)}
.iq-note{margin:12px 0}
/* HOW TO ANSWER. It sits directly above the first question and reads at body
   size, because it is the calibration and not a footnote. */
.iq-acc{margin:14px 0 18px}
.iq-accg{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.iq-accp{padding:14px 15px 15px;border-radius:var(--r-s);background:var(--panel-2);
 border:1px solid var(--edge);border-top:2px solid var(--gold)}
body.punch .iq-accp{border-color:transparent;border-top-color:var(--gold)}
.iq-accp p{font-size:13px;line-height:1.7;color:var(--mid);margin:8px 0 0}
.iq-accw{font-size:13px;line-height:1.7;color:var(--dim);margin:11px 0 0;max-width:86ch}
@media (max-width:1180px){.iq-accg{grid-template-columns:1fr}}
.iq-sc-key{margin:11px 0 0;padding:11px 15px;border-radius:var(--r-s);
 background:var(--sunk);border:1px solid var(--edge);
 font-size:12.5px;color:var(--dim);display:flex;gap:7px;flex-wrap:wrap;align-items:baseline}
.iq-sc-key b{font-family:var(--num);font-size:14px;font-weight:500;color:var(--gold);
 margin-right:2px}
.iq-sc-key span{color:var(--edge-2)}
body.punch .iq-sc-key{border-color:transparent}

.iq-grid{display:grid;gap:16px}
/* ONE SEGMENT PER SEAT, crown down to root. The group carries the colour so
   the law rows inside it do not have to repeat it seven times over. */
.iq-seg{border-radius:var(--r-s);padding:0 0 2px;
 background:color-mix(in srgb,var(--c) 4%,var(--panel));
 border:1px solid color-mix(in srgb,var(--c) 22%,var(--edge))}
body.punch .iq-seg{border-color:transparent;background:color-mix(in srgb,var(--c) 9%,var(--panel))}
.iq-sh{display:flex;align-items:baseline;gap:10px;padding:12px 15px 11px;
 background:color-mix(in srgb,var(--c) 9%,transparent);
 border-bottom:1px solid color-mix(in srgb,var(--c) 26%,var(--edge))}
body.punch .iq-sh{border-bottom-color:transparent}
.iq-shn{font-size:15px;font-weight:500;color:var(--c);letter-spacing:.01em}
.iq-shd{font-size:12.5px;color:var(--dim)}
.iq-gl{width:22px;height:22px;flex:0 0 auto;display:grid;place-items:center;
 color:var(--c);align-self:center}
.iq-gl svg{width:var(--icon-nav);height:var(--icon-nav);fill:none;stroke:currentColor;stroke-width:1.5;
 stroke-linecap:round;stroke-linejoin:round}
.iq-gl.big svg{width:19px;height:19px}
/* TWO LAW CARDS ACROSS, NOT THREE QUESTIONS ACROSS. Drawn by the owner, and
   it corrects the layout that went in an hour before it. A law is the unit a
   person works in, so a law is the card. Its three framings stack inside it,
   which is where they were, and the horizontal room that was going to waste
   holds a second law instead of a third question. */
.iq-laws{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:8px;
 align-items:start}
.iq-law{border:1px solid color-mix(in srgb,var(--c) 34%,var(--edge));
 border-radius:var(--r-s);overflow:hidden;background:var(--panel-2)}
.iq-law.done{border-color:color-mix(in srgb,var(--c) 52%,var(--edge))}
/* AN OPEN LAW STAYS IN ITS COLUMN, which is what the owner drew: two law
   cards side by side, each holding its own three framings stacked.

   I had it spanning the row on the assumption that half a column would put the
   eleven step scale under the tap floor. The arithmetic says otherwise. Half a
   column is 428, less the card border and the question padding is 410, and six
   cells across that is 68 each, well over the 44 floor and wider than the 45
   the three across version produced. The assumption was wrong and the drawing
   was right. */
.iq-law.open{border-color:var(--c)}
.iq-hd{display:flex;align-items:center;gap:10px;width:100%;background:transparent;border:0;
 padding:11px 13px;cursor:pointer;color:var(--ink);font-family:var(--sans);text-align:left;
 min-height:var(--tap)}
.iq-hd:hover{background:var(--sunk)}
.iq-nm{font-size:15px;font-weight:500;flex:1 1 auto}
.iq-bd{font-size:12px;color:var(--dim)}
.iq-sc{font-family:var(--num);font-size:16px;font-weight:500;color:var(--gold);
 min-width:34px;text-align:right;font-variant-numeric:tabular-nums}
.iq-sc.todo{font-size:12.5px;color:var(--dim);font-family:var(--sans);min-width:0}
.iq-find{font-size:12.5px;color:var(--dim);padding:0 13px 10px;line-height:1.6}
.iq-find.open{grid-column:1/-1;border-left:3px solid var(--c);margin:2px 0 0;padding:10px 13px;
 background:color-mix(in srgb,var(--c) 10%,transparent);
 border-radius:0 var(--r-xs) var(--r-xs) 0;font-size:13.5px;color:var(--mid)}
.iq-seat{color:var(--dim);font-size:12.5px}
/* THREE FRAMINGS OF ONE LAW, SIDE BY SIDE. The gap between them is the
   reading, so all three have to be on the screen at the same time. */
/* the three framings stack inside the law card. The gap between them is the
   reading and all three are in one card, which is what puts them together. */
.iq-qs{display:grid;grid-template-columns:1fr;gap:7px;padding:2px 8px 12px}
@media (max-width:1240px){.iq-laws{grid-template-columns:1fr}}
.iq-qc{border-radius:var(--r-xs);padding:11px 3px 6px;min-width:0;
 background:color-mix(in srgb,var(--c) 19%,var(--panel-2));
 border:1px solid color-mix(in srgb,var(--c) 40%,var(--edge))}
body.punch .iq-qc{border-color:transparent;background:color-mix(in srgb,var(--c) 26%,var(--panel-2))}
.iq-qt{font-size:13.5px;line-height:1.55;color:var(--mid);margin:0 5px 9px;font-weight:300}
.iq-qt em{display:block;margin-bottom:5px;color:var(--c);font-style:normal}
/* six across, two rows, and the ten is wide because it is the anchor the note
   above defines. Every cell clears the 44px tap floor at the narrowest
   column this grid produces. */
/* The outer edge is an inset shadow, not a border. A border would take two
   pixels out of a column that has none to give, and the cells fall under the
   44px tap floor by a fraction, which is exactly the failure the design gate
   warns is not deterministic. A shadow draws the same line for no layout. */
/* ZERO TO TEN ON ONE LINE, AND THE CELLS ARE EVEN. Both ruled, and they were
   one fault.

   Eleven buttons in six columns is two rows, and eleven into six leaves one
   over, so the ten was given grid-column:span 2 to fill the gap. A scale whose
   last step is twice the width of every other step is not a scale, it is a
   scale with an argument about ten in it, and a scale that wraps is two
   scales. Eleven columns, one row, every cell identical.

   The cards hold at three across down to 1180, below which they stack and each
   scale gets the full width of the card, so eleven cells never fall under the
   tap floor. */
.iq-sl{display:grid;grid-template-columns:repeat(11,1fr);
 border-radius:var(--r-xs);overflow:hidden;box-shadow:inset 0 0 0 1px var(--edge)}
body.punch .iq-sl{box-shadow:none}
.iq-n{min-height:var(--tap);border:0;border-right:1px solid var(--edge);
 background:var(--sunk);color:var(--mid);font-family:var(--num);font-size:13px;font-weight:500;cursor:pointer;transition:background var(--t-micro) var(--ease-out),color var(--t-micro) var(--ease-out)}
.iq-n:last-child{border-right:0}
.iq-n:hover{background:var(--panel);color:var(--ink)}
.iq-n.on{background:var(--c);border-color:var(--c);color:var(--on-accent);font-weight:600}
@media (max-width:1180px){.iq-qs{grid-template-columns:1fr}}
/* ON A PHONE THE ELEVEN CELLS STAY ON ONE LINE, his ruling ("a scale that wraps
   is two scales"), so each is about thirty wide. Round OK, his words: "just
   make it legible so it looks good and doesn't break." The digit is larger and
   heavier, the cell keeps the 44 high tap floor, and the number in the cell
   never wraps or clips. */
@media (max-width:520px){.iq-n{font-size:15px;font-weight:600;padding:0;min-width:0;letter-spacing:-.02em;
 display:flex;align-items:center;justify-content:center}}

/* ============================================================
   RELEASE AND RITUAL
   ============================================================ */
.rel{position:fixed;inset:0;z-index:90;display:none;align-items:center;justify-content:center;
 background:rgba(8,9,13,.76);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
body.snow .rel{background:rgba(238,237,233,.82)}
.rel-card{width:min(560px,93vw);max-height:88vh;overflow-y:auto;padding:30px 32px;
 border-radius:var(--r);background:var(--panel);border:1px solid var(--edge);
 box-shadow:0 26px 64px rgba(0,0,0,.5);text-align:center}
.rel-speak{font-size:22px;line-height:1.6;margin:22px 0;min-height:70px;color:var(--ink);font-weight:300}
.rel-dots{display:flex;gap:6px;justify-content:center;margin-bottom:22px}
.rel-dots i{width:7px;height:7px;border-radius:50%;background:var(--sunk)}
.rel-dots i.on{background:var(--gold)}
.rel-node{font-size:30px;font-weight:600;margin:14px 0 5px;letter-spacing:0}
.rel-sub{font-size:13.5px;color:var(--dim);margin-bottom:17px}
.rel-side{display:flex;justify-content:center;margin:17px 0}
/* the thought line. Read in thought at the speed of the run, so it is set at
   body size in the ink and not at display size: the address above it is what
   the eye returns to, and the sentence is what it follows once. The height
   is held at five lines, the median line at 390 wide when this was measured
   on 26 September, because the longest line is more than twice the shortest
   and without it Pause and Stop moved under a finger on every line. */
.rel-line{font-size:16px;line-height:1.6;color:var(--ink);font-weight:300;margin:6px 0 4px;
 min-height:8em}
.rel-line.tru{color:var(--mid)}
.rel-side span{font-family:var(--num);font-size:12.5px;padding:7px 22px;
 border-radius:22px;border:1px solid var(--edge);color:var(--mid)}
.rel-R span{margin-left:34%;border-color:rgba(223,204,126,.5);color:var(--gold)}
.rel-L span{margin-right:34%;border-color:rgba(123,151,226,.5);color:var(--eye)}
.rel-prog{height:6px;background:var(--sunk);border-radius:3px;overflow:hidden;margin:20px 0 8px}
.rel-prog i{display:block;height:100%;border-radius:3px;transition: width var(--t-context) var(--ease-out)}
.rel-ct{font-family:var(--num);font-size:12.5px;color:var(--dim)}
.rel-log{display:flex;flex-direction:column;gap:3px;margin:15px 0;text-align:left;
 max-height:260px;overflow-y:auto}
.rel-row{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;
 font-size:13.5px;color:var(--mid);padding:6px 8px;border-radius:var(--r-xs)}
.rel-row.cleared{background:rgba(104,203,164,.12);color:var(--ink)}
.rel-row em{font-style:normal;font-size:12px;color:var(--heart)}
.rel-row b{font-weight:500;color:var(--gold);font-family:var(--num);font-variant-numeric:tabular-nums}
.rel-note{font-size:13.5px;color:var(--dim);line-height:1.7;margin:13px 0 19px;text-align:left;font-weight:300}
.rel-act{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
/* PAUSE AND END, LOWER RIGHT, AND STUCK THERE, round LY: "pause and end need
   to go on the lower right." The first cut moved them later in the card's
   own order, after the counts, the clock and the switches, which put them
   lower in the reading but not lower on the screen: measured, the card
   itself scrolls (.rel-card's own max-height:88vh), and a run with the
   switches showing pushed Pause forty pixels under the card's own visible
   bottom edge, the opposite of reachable. ritual.js's own action row
   already answers the same problem the same way (body.tab-ritual #rit
   .rel-act{position:sticky;bottom:0}), so this follows it: sticky to the
   card's own scrolling bottom, right aligned, its own backdrop so the
   counts do not show through it while it holds there, and the card's own
   side padding pulled back in by negative margin so the backdrop reaches
   the card's true edge rather than leaving a gap either side of it. */
/* -44 not -32: .rel-card.rel-running overrides the side padding to 44px, for
   the strips, and a bar pulled back only to the base 32 left a eleven pixel
   sliver of strip showing under its own left edge, measured. */
.rel-act-lr{justify-content:flex-end;margin:18px -44px 0 -44px;padding:12px 44px 30px;
 position:sticky;bottom:-30px;background:var(--panel);z-index:1}
/* THE RELEASE, HEARD (DESIGN-release.md section 6). The card while a run is
   under way carries a strip on each side, the live one lit and carrying its
   word, so the side is never told by colour alone. The strips sit inside the
   card's own padding, which is why the running card is inset further. */
.rel-card.rel-running{position:relative;padding-left:44px;padding-right:44px}
.rel-strip{position:absolute;top:0;bottom:0;width:30px;display:flex;align-items:center;
 justify-content:center;color:var(--dim);font-size:11px;font-weight:600;letter-spacing:.04em}
.rel-strip span{writing-mode:vertical-rl;transform:rotate(180deg);white-space:nowrap}
.rel-strip-L{left:0;border-right:1px solid var(--edge)}
.rel-strip-R{right:0;border-left:1px solid var(--edge)}
.rel-strip.on{color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,transparent)}
.rel-plate{display:flex;align-items:center;justify-content:center;gap:12px;margin:14px 0 6px;text-align:left}
.rel-plate .rel-node{display:block;font-size:22px;margin:0}
.rel-plate .rel-sub{display:block;margin:0}
/* a pass is four or five words and is read at a glance, so it is set larger
   than the head statement it repeats */
.rel-line.pass{font-size:22px;font-weight:400}
.rel-clock{display:flex;align-items:center;justify-content:center;gap:22px;margin:16px 0 18px}
.rel-dial{display:block;flex:none}
.rel-fig{display:flex;flex-direction:column;align-items:flex-start;gap:2px}
.rel-fig span{font-size:11px;font-weight:600;letter-spacing:.06em;color:var(--dim)}
.rel-fig b{font-family:var(--num);font-variant-numeric:tabular-nums;font-size:20px;font-weight:500;color:var(--ink)}
.rel-cool{margin:14px 0 10px}
/* the selection, shown as its rings and nothing else: it was made upstream */
.rel-rings{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin:16px 0 6px}
.rel-fields{display:flex;justify-content:center;gap:14px;flex-wrap:wrap;margin:18px 0 22px}
.rel-field{display:flex;flex-direction:column;align-items:flex-start;gap:6px;text-align:left}
.rel-field span{font-size:11px;font-weight:600;letter-spacing:.06em;color:var(--dim)}
.rel-field input,.rel-field select{min-height:44px;min-width:96px;padding:9px 12px;
 background:var(--panel-2);color:var(--ink);border:1px solid var(--edge);border-radius:var(--r-xs);
 font-family:var(--num);font-size:16px;text-align:center}
/* Time, round LY: a read out and not an input, so it is not boxed like the
   two fields beside it, but it holds their own height so the row of three
   does not jump when it lands. */
.rel-field .rel-time{display:flex;align-items:center;justify-content:center;min-height:44px;min-width:96px;
 font-family:var(--num);font-variant-numeric:tabular-nums;font-size:16px;color:var(--ink)}
.rel-card .ac-tog+.ac-tog{margin-top:0;border-top:0}
/* THE SEAT TONE'S SWITCH, IN THE RELEASE. The account page's own row, taken
   out to the card's edges so its label starts on the line the text above it
   starts on, where the row's own inset left it floating fifteen pixels in.
   A hairline parts it from Pause and Stop, because it is a setting and they
   are the run. Lumen already clears every border on this row; Punch outlines
   nothing, so the hairline goes there too and the gap does the parting. */
.rel-card .ac-tog{margin-top:18px;padding:12px 0 0;border-bottom:0;
 border-top:1px solid var(--edge);text-align:left}
body.punch .rel-card .ac-tog{border-top-color:transparent}
.rit-card{width:min(640px,94vw);text-align:left}
.rit-card .rel-node,.rit-card .rel-sub{text-align:left}
.rit-from{font-family:var(--num);font-size:12.5px;color:var(--gold);margin:10px 0 3px}
.rit-list{margin:15px 0 0;max-height:330px;overflow-y:auto}
.rit-tr{margin:13px 0 6px;color:var(--c)}
.rit-row{display:grid;grid-template-columns:10px 1fr auto;gap:10px 11px;width:100%;text-align:left;
 background:transparent;border:1px solid transparent;border-radius:var(--r-xs);padding:10px 12px;
 cursor:pointer;color:var(--mid);font-family:var(--sans);margin-bottom:3px;transition:all var(--t-micro) var(--ease-out)}
.rit-row:hover{background:var(--panel-2)}
.rit-row.on{background:rgba(223,204,126,.16);border-color:rgba(223,204,126,.4);color:var(--ink)}
.rit-row i{width:10px;height:10px;border-radius:50%;align-self:center}
.rit-nm{font-size:15px;font-weight:500}
.rit-nm em{font-style:normal;font-size:11px;font-weight:600;color:var(--gold)}
.rit-d{grid-column:2;font-size:12.5px;color:var(--dim);margin-top:-2px;line-height:1.55}
.rit-row b{font-family:var(--num);font-size:13px;font-weight:500;color:var(--dim);align-self:center}
.rit-how{margin-top:9px;max-height:250px;overflow-y:auto}
.rit-step{margin-bottom:13px}
.rit-step b{font-size:15px;font-weight:600;display:block;margin-bottom:5px}
.rit-step p{font-size:14px;line-height:1.7;color:var(--mid);margin:0;font-weight:300}
/* TODAY'S RITUAL, READ BACK. The plan sits above the builder, because a plan
   already made is what the surface is for and making another is the second
   thing a person wants from it. Left edge in the seat colour of the accent,
   which is how everything else in this product marks a live thing. */
.rit-saved{margin:14px 0 4px;padding:12px 14px;border:1px solid var(--edge);
 border-left:2px solid var(--accent);border-radius:var(--r-s);background:var(--panel-2)}
.rit-saved.done{border-left-color:var(--heart)}
.rit-sv-h{font-size:15px;font-weight:500;color:var(--ink);margin:3px 0 6px}
.rit-sv-h b{font-family:var(--num);font-size:13px;font-weight:500;color:var(--dim)}
.rit-sv-p{margin:0 0 9px;font-size:13.5px;line-height:1.6;color:var(--mid)}
.rit-sv-ok{color:var(--heart);margin-bottom:0}
/* ONE PRACTICE, AND THE WAY TO THE REST. Not a disclosure triangle: a sentence
   that says how many there are, because a control that hides an unknown
   quantity is a control a person does not press. */
.rit-list.one{max-height:none;overflow:visible}
.rit-more{display:block;width:100%;margin:10px 0 0;padding:9px 12px;
 min-height:var(--tap);background:none;border:1px dashed var(--edge-2);
 border-radius:var(--r-s);color:var(--dim);font:inherit;font-size:13px;
 cursor:pointer;text-align:left;transition:color var(--t-micro) var(--ease-out),
 border-color var(--t-micro) var(--ease-out)}
.rit-more:hover{color:var(--ink);border-color:var(--accent)}
/* THE IF THEN PLAN. Two fields and the sentence they make, which is the whole
   mechanism: a plan naming a time and a place is acted on. The sentence is
   under the fields rather than above them so it fills in as they are typed. */
.rit-plan{margin:16px 0 0;padding-top:14px;border-top:1px solid var(--edge)}
.rit-f{display:flex;align-items:center;gap:11px;margin:9px 0}
.rit-f span{flex:0 0 52px;font-family:var(--num);font-size:11px;color:var(--dim)}
.rit-f input{flex:1 1 auto;min-height:var(--tap);padding:7px 11px;
 background:var(--sunk);border:1px solid var(--edge);border-radius:var(--r-xs);
 color:var(--ink);font:inherit;font-size:14px}
.rit-f input:focus-visible{outline:2px solid var(--accent);outline-offset:1px;
 border-color:var(--accent)}
.rit-if{margin:9px 0 0;font-size:13.5px;line-height:1.6;color:var(--mid)}
/* THE RECORD, on the surface that earns it as well as inside the Compass. */
.rit-rec{margin-top:18px;padding-top:15px;border-top:1px solid var(--edge)}
:root{--tip-bg:#1A1D26;--tip-edge:rgba(255,255,255,.14);--tip-shadow:0 10px 24px rgba(0,0,0,.38)}
body.snow{--tip-bg:#F8F7F3;--tip-edge:rgba(20,23,28,.18);--tip-shadow:0 10px 24px rgba(20,22,28,.13)}
/* ============================================================
   THE TIP. This block is the whole of the tooltip's CSS.
   Copy it into atuned_src/shell/head.html as one block.
   ============================================================ */
.tip{
 position:fixed; left:0; top:0; z-index:60;
 box-sizing:border-box;
 width:max-content; max-width:300px; min-width:0;
 padding:12px 14px 13px;
 /* EVERY var() HERE CARRIES A FALLBACK, and it is not belt and braces.
    Injected into the live build for the measurement run, --tip-bg was not
    declared and background:var(--tip-bg) resolved to nothing: the tooltip
    rendered with a transparent ground in Dark and in Snow, the two lightings
    most of this audience will ever see. An unresolved var reads as empty and
    fails silently, which is the fault DESIGN.md law 7 already names for the
    motion tokens. A fallback turns a missing declaration into a wrong shade
    rather than into an invisible panel. */
 background:var(--tip-bg,var(--panel,#1A1D26));
 border:1px solid var(--tip-edge,var(--edge-2,rgba(255,255,255,.14)));
 border-radius:var(--r-s,11px);
 /* THE TOOLTIP STATES ITS OWN SHADOW rather than inheriting --shadow.
    Measured over the live Field: with --shadow, Glass ran 53.2 frames a
    second closed and 47.1 with the panel open, a loss of 6.1. Glass's shadow
    is a 64 pixel blur and a large radius soft shadow over a canvas that
    repaints every frame is recomposited every frame. At 24 pixels the loss
    is inside the noise. The tooltip is a small floating object and it may
    not cost the Field anything. */
 box-shadow:var(--tip-shadow,0 10px 24px rgba(0,0,0,.38));
 font-family:var(--sans); font-size:13px; line-height:1.65;
 color:var(--mid);
 /* the panel is reachable, so a long definition can be scrolled and a link
    inside it followed. the 10px gap plus a 120ms grace is what makes the
    crossing survivable. */
 pointer-events:auto;
 opacity:0; visibility:hidden;
 transform:translate(var(--dx,0px),var(--dy,0px)) scale(.972);
 transform-origin:var(--ox,50%) var(--oy,50%);
 transition:opacity var(--t-micro) var(--ease-in),
            transform var(--t-micro) var(--ease-in),
            visibility 0s linear var(--t-micro);
}
.tip.on{
 opacity:1; visibility:visible;
 transform:translate(0,0) scale(1);
 transition:opacity var(--t-element) var(--ease-out),
            transform var(--t-element) var(--ease-out),
            visibility 0s;
}
/* THE ENTRY MARK. Thirty pixels of the carrier's own colour lying along the
   panel's near edge, centred on the tether's foot. With the tether it makes
   one T, forty pixels of continuous stroke, and the T is where the line
   arrives. It replaces the caret every other tooltip draws without being a
   caret: an arrow points, and this says the colour came through here.

   It ran the full width first. At 284 pixels it read as a header rule rather
   than as an arrival, and it overshot the eleven pixel corner radius and cut
   the corner square. Both gone at thirty.

   Ring, not fill: it is an edge, never a wash. The colour is only ever a
   graphic here. Root is 4.17 to 1 on this ground and would fail as text; as a
   two pixel stroke it is past the 3 to 1 floor a graphic is held to. */
.tip::after{
 content:''; position:absolute; background:var(--tc,var(--accent));
 border-radius:1px;
}
.tip[data-side=bottom]::after{left:var(--tx,50%);top:0;width:30px;height:2px;margin-left:-15px}
.tip[data-side=top]::after   {left:var(--tx,50%);bottom:0;width:30px;height:2px;margin-left:-15px}
.tip[data-side=right]::after {top:var(--ty,50%);left:0;height:30px;width:2px;margin-top:-15px}
.tip[data-side=left]::after  {top:var(--ty,50%);right:0;height:30px;width:2px;margin-top:-15px}
/* THE TETHER. Ten pixels of the same colour crossing the gap, drawn from the
   carrier's end. It is the cause, and it leads the panel by sixty
   milliseconds so the eye is already at the destination when the panel
   lands. A tooltip that fades in place makes the eye search for what caused
   it. This one grows out of its carrier. */
.tip::before{
 content:''; position:absolute; background:var(--tc,var(--accent));
 transform:scale(0); transition:transform 0s linear;
}
.tip.on::before{transform:scale(1); transition:transform var(--t-micro) var(--ease-out)}
.tip[data-side=bottom]::before{left:var(--tx,50%);top:-10px;width:2px;height:10px;margin-left:-1px;transform-origin:50% 0}
.tip[data-side=top]::before   {left:var(--tx,50%);bottom:-10px;width:2px;height:10px;margin-left:-1px;transform-origin:50% 100%}
.tip[data-side=right]::before {top:var(--ty,50%);left:-10px;height:2px;width:10px;margin-top:-1px;transform-origin:0 50%}
.tip[data-side=left]::before  {top:var(--ty,50%);right:-10px;height:2px;width:10px;margin-top:-1px;transform-origin:100% 50%}

.tip-k{font-family:var(--num);font-size:11.5px;line-height:1.3;color:var(--dim);
 letter-spacing:.02em;font-variant-numeric:tabular-nums;margin:0 0 3px}
.tip-t{font-size:13px;line-height:1.3;font-weight:600;color:var(--ink);margin:0 0 6px}
.tip-b{margin:0}
/* THE NUMBERS. Every one says what it is out of. tipNum refuses a value
   with no denominator, which is why the slot is a grid of three and not a
   line of text. */
.tip-n{display:grid;grid-template-columns:auto 1fr;gap:1px 10px;margin:9px 0 0;
 font-family:var(--num);font-size:11.5px;line-height:1.5;
 font-variant-numeric:tabular-nums;letter-spacing:.01em}
.tip-n dt{color:var(--dim);margin:0}
.tip-n dd{color:var(--ink);margin:0;font-weight:500}
.tip-n dd i{font-style:normal;color:var(--dim);font-weight:400}
.tip-a{margin:9px 0 0;font-size:12px;line-height:1.4;font-weight:500;color:var(--accent)}
/* A LONG DEFINITION SCROLLS, and the cut is masked so it never reads as the
   end of the sentence. The mask is on the body, not on the panel, because a
   mask on the panel would eat the edge bar. */
.tip-s{max-height:38vh;overflow:auto;overscroll-behavior:contain;
 -webkit-mask-image:linear-gradient(#000 calc(100% - 22px),transparent);
 mask-image:linear-gradient(#000 calc(100% - 22px),transparent);
 padding-bottom:12px}
.tip-s::-webkit-scrollbar{width:4px}
.tip-s::-webkit-scrollbar-thumb{background:var(--edge-2);border-radius:2px}

/* THE PHONE. A coarse pointer has no hover and no room, so the panel becomes
   a sheet at the bottom of the window. It never covers the carrier because
   the carrier is above it, and tipShow scrolls the carrier clear first when
   the two would overlap. The class is set by script from the pointer query
   and the width, not by a media query alone, because a media query cannot
   say "or narrow" and a gate cannot force one. */
body.tip-sheet .tip{
 left:8px; right:8px; top:auto; bottom:8px;
 bottom:calc(8px + env(safe-area-inset-bottom,0px));
 width:auto; max-width:none; border-radius:var(--r);
 padding:14px 16px 16px;
 transform:translateY(12px);
 transform-origin:50% 100%;
}
body.tip-sheet .tip.on{transform:translateY(0)}
body.tip-sheet .tip::before{display:none}
body.tip-sheet .tip::after{left:16px;right:16px;top:0;bottom:auto;height:2px;width:auto;margin-left:0}
/* THE SHEET AT THE TOP. Same object, same motion, mirrored: it travels down
   from the top edge instead of up from the bottom, so the direction still
   says where it came from. */
body.tip-sheet .tip.top{top:8px;top:calc(8px + env(safe-area-inset-top,0px));bottom:auto;
 transform:translateY(-12px);transform-origin:50% 0}
body.tip-sheet .tip.top.on{transform:translateY(0)}
body.tip-sheet .tip.top::after{top:auto;bottom:0}
body.tip-sheet .tip-s{max-height:45vh}
body.tip-sheet .tip-x{
 display:block;position:absolute;right:6px;top:6px;
 width:var(--tap);height:var(--tap);min-width:var(--tap);min-height:var(--tap);
 background:none;border:0;border-radius:var(--r-xs);cursor:pointer;
 color:var(--dim);font:inherit;line-height:1;
 transition:color var(--t-micro) var(--ease-out)}
body.tip-sheet .tip-x:hover{color:var(--ink)}
body.tip-sheet .tip-x svg{width:18px;height:18px;fill:none;stroke:currentColor;
 stroke-width:1.6;stroke-linecap:round}
body.tip-sheet .tip{padding-right:52px}
.tip-x{display:none}
/* THE OPEN CARRIER IS MARKED, AND ONLY ON THE SHEET. On a fine pointer the
   tether already says which word this belongs to. On a phone there is no
   tether, the sheet is eight hundred pixels from the word, and nothing
   connects the two. So the carrier takes a two pixel ring in its own colour
   while its sheet is open, and the sheet's entry mark is the same colour.
   Two objects, one colour, and that is the whole connection.

   box-shadow rather than outline, because a ring carrier is round and a
   rectangular outline around a circle is a second shape. */
body.tip-sheet [data-tip].tip-open,
body.tip-sheet [data-tip-t].tip-open{
 box-shadow:0 0 0 2px var(--c,var(--accent));
 border-radius:var(--r-xs)}

/* PUNCH. Nothing is outlined, so --edge is transparent and the hairline
   vanishes. The separation becomes a solid step, the same move every other
   Punch control makes. */
body.punch{--tip-bg:var(--panel-2); --tip-edge:transparent}
/* GLASS. --panel is rgba there. The tooltip states the composited value as an
   opaque colour instead, because it floats over the wheel and gate 13 will
   not let it carry a backdrop-filter to earn its translucency. */
body.glass{--tip-bg:#151922; --tip-edge:rgba(255,255,255,.17);
 --tip-shadow:0 10px 24px rgba(0,0,0,.46)}
body.glasswhite{--tip-bg:#F6F6F4; --tip-edge:rgba(20,22,28,.18);
 --tip-shadow:0 10px 24px rgba(20,22,28,.13)}
/* Flat has no shadow anywhere. The tooltip does not get one either: its
   separation is the one pixel edge, which Flat states at full strength. */
body.flat{--tip-bg:#121419; --tip-edge:#2E333E; --tip-shadow:none}
body.lumen{--tip-bg:#FFFFFF; --tip-edge:rgba(16,16,16,.22);
 --tip-shadow:0 10px 24px rgba(0,0,0,.14)}

/* REDUCED MOTION. Opacity only, and still 120ms rather than none: a panel
   that appears with no elapsed time reads as a glitch rather than as an
   answer. The tether stops growing and is simply there. */
@media (prefers-reduced-motion:reduce){
 .tip,.tip.on{transform:none !important}
 .tip{transition:opacity var(--t-micro) linear,visibility 0s linear var(--t-micro)}
 .tip.on{transition:opacity var(--t-micro) linear,visibility 0s}
 .tip::before,.tip.on::before{transform:scale(1);transition:none}
}
body.rm .tip,body.rm .tip.on{transform:none !important}
body.rm .tip{transition:opacity var(--t-micro) linear,visibility 0s linear var(--t-micro)}
body.rm .tip.on{transition:opacity var(--t-micro) linear,visibility 0s}
