body.tab-intake #iq{display:flex!important;z-index:5;overflow-y:auto}
body:not(.tab-intake) #iq{display:none!important}
body.tab-questions #iqp{display:flex!important;z-index:5;overflow-y:auto}
body:not(.tab-questions) #iqp{display:none!important}
body.tab-story #story{display:flex!important;z-index:5;align-items:center;justify-content:center}
body:not(.tab-story) #story{display:none!important}
body.tab-energy #emap{display:flex!important;z-index:5}
body:not(.tab-energy) #emap{display:none!important}
/* the Character page keeps the Masks door's host and its terms: shown and
   hidden exactly the way the Body is */
body.tab-masksview #masksview{display:flex!important;z-index:5}
body:not(.tab-masksview) #masksview{display:none!important}
/* THE CHARACTER PAGE, round LP: pixel grids, each under its name "in very
   small, simple font", and one switch for the reading. ui/character.js
   writes it. The grids sit on the render ground like the Field, MK2's "almost
   like a UI display", and the page scrolls inside its host at a desktop
   width, because the hero and a switch are taller than a short window. */
.chv{flex:1 1 auto;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:14px;
 padding:18px 22px 24px;color:var(--ink)}
.chv-top{display:flex;justify-content:flex-end}
.chv-empty{margin:0 auto;max-width:880px;width:100%;font-size:13px;line-height:1.5;color:var(--mid)}
/* THE RAIL AND THE HERO, ROUNDS MX, MZ AND NA, replacing the three column
   grid this host used to draw (.chv-m and .chv-svg below are the same
   classes that grid used, kept rather than renamed, since the rail's own
   icons and the pair in Selection, .chv-pair, still need exactly what
   they always did). His words at MX: "we have all five masks as small
   icons on the left hand side of the screen... but then it gives us, we
   can maximize the rest of that space." The grid gave every mask the same
   small square and used none of the width a wide desktop actually has,
   five squares in a row above a blank field. .chv-stage is a row so the
   rail sits on the left in source order and the hero second, flex:1 so it
   takes whatever width the rail does not. Order is swapped on phone below
   by CSS order, never by rewriting the markup: character.js only rewrites
   #masksview when the html string it built actually changed, the same
   caution its own hover handler keeps for a hover a hand is resting on. */
.chv-stage{display:flex;flex-direction:row;gap:18px;flex:1 1 auto;min-height:0;width:100%}
.chv-rail{display:flex;flex-direction:column;gap:10px;flex:0 0 auto;align-items:center}
.chv-hero{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;
 flex:1 1 auto;min-height:0;min-width:0;text-align:center}
/* SHRUNK, ROUND NN: "the Child text is taking up too much real estate...
   maximize that area." The name stays, his own round NK ruling that the
   hero keeps it while the rail does not, but its own footprint comes down,
   11px and a 4px gap rather than 14px and 10px, so more of .chv-hero's own
   height, bounded by .chv-stage above it, goes to the face and not the
   label sitting over it. */
.chv-hero-nm{font-size:11px;letter-spacing:.02em;color:var(--mid)}
/* THE NAME COMES OFF THE RAIL, ROUND NK: "I don't want the buttons that
   tall. Shrink the icons down. Remove the name above it so you get more
   space of the icons. And then keep the name above the major symbol,"
   his own word for the hero, which is why .chv-hero-nm above is untouched
   and only this button's own padding and the icon size below move. The
   name is still read aloud: ui/character.js keeps it on title and
   aria-label both, so nothing a screen reader says changed, only what a
   sighted person sees printed under five small icons in a row. */
.chv-m{display:flex;align-items:center;justify-content:center;min-width:0;padding:4px;
 background:transparent;border:1px solid transparent;border-radius:var(--r-s);color:var(--mid);
 font:inherit;cursor:pointer;position:relative}
/* LIT, NOT PRESSED, ROUND NK. DESIGN-character-effects.md 2: "an edge drawn
   round a control is a form button," which both the old aria-pressed gold
   border and the old hover edge were, and the Field never selects that
   way, Sol's own reading, "the chosen chain saturates rather than lights"
   (wheel.js, "saturates rather than lights" near line 1163). Rest holds
   the icon at .45 saturation, hover lifts it to .75, and selected drops
   the filter back to none and lights the pool below instead, so the thing
   that changes is the icon's own colour and never a line drawn around it. */
.chv-m .chv-svg{filter:saturate(.45);transition:filter var(--t-element) var(--ease-out)}
.chv-m:hover .chv-svg{filter:saturate(.75)}
.chv-m[aria-pressed=true] .chv-svg{filter:none}
/* THE POOL, a radial glow behind the icon and never a ring round it, in the
   mask's own top seat colour. character.js sets --mk-top inline, the same
   seatCol(m.b[m.b.length-1]) lookup chSvg's own rim already runs for the
   right half of the face, rather than this file re-deriving which of a two
   seat mask's colours is the one to light. Hover and selected share one
   gradient and differ only in how strong it reads, 8% against 20%, so
   hovering a mask previews the colour its own selection would light. */
.chv-m::before{content:'';position:absolute;inset:0;border-radius:var(--r-s);pointer-events:none;
 opacity:0;transition:opacity var(--t-element) var(--ease-out);
 background:radial-gradient(closest-side,color-mix(in srgb,var(--mk-top,var(--accent)) 8%,transparent),transparent)}
.chv-m:hover::before{opacity:1}
.chv-m[aria-pressed=true]::before{opacity:1;
 background:radial-gradient(closest-side,color-mix(in srgb,var(--mk-top,var(--accent)) 20%,transparent),transparent);
 animation:chvBreath var(--t-breath) var(--ease-breath) infinite}
/* SNOW, round NK: the same 20% mix sat right on paper rather than the
   black stage the number above was measured on, so Snow gets its own
   figure rather than inheriting Dark's. Glass reads as Dark, Sol's own
   ruling, since it is the same seat palette under a different sheen. */
body.snow .chv-m[aria-pressed=true]::before{
 background:radial-gradient(closest-side,color-mix(in srgb,var(--mk-top,var(--accent)) 14%,transparent),transparent)}
/* PUNCH NEVER GLOWS, round NK: its own rule already standing everywhere
   else a control in this file is selected, body.punch .ib[aria-pressed]
   among them, is that a chosen thing is a fill and not a light. The pool
   becomes a flat wash toward --sunk instead of a gradient, and the breath
   comes off with it: a fill has no soft edge to breathe. */
body.punch .chv-m[aria-pressed=true]::before{
 background:color-mix(in srgb,var(--mk-top,var(--accent)) 22%,var(--sunk));animation:none}
.chv-m:focus-visible{outline:2px solid var(--gold);outline-offset:2px}
/* THE WEAVE'S OWN RAIL STATE. MX left the routing question open on purpose,
   "how the lines draw once one mask can be large and the others a rail":
   no line crosses the gap, because a rail icon and the hero are two
   different sizes and a line between them would have to bend around every
   icon in between. Instead the matching pixel is ringed on every mask that
   carries it, .chv-weavepx below, and the icon that holds one gets this
   glow too, so "does this show up here" answers at a glance before a
   reader has found the one lit cell inside a 64 pixel square. */
.chv-m.chv-weave-on{box-shadow:0 0 0 2px var(--accent)}
