 animation:chvBreath var(--t-breath) var(--ease-breath) infinite}
body.snow .chv-hero-wrap::before{
 background:radial-gradient(60% 60% at 50% 49%,color-mix(in srgb,var(--mk-top,var(--accent)) 14%,transparent),transparent)}
body.punch .chv-hero-wrap::before{
