   clock instead, "holding and breathing when steady." */
.chv-hotcell{transform-box:fill-box;transform-origin:center}
.chv-hotcell.chv-hot-exp{animation:chvHotWave 1.1s ease-in-out infinite;animation-delay:calc(var(--k,0) * .18s)}
.chv-hotcell.chv-hot-col{animation:chvHotWave 1.1s ease-in-out infinite reverse;animation-delay:calc(var(--k,0) * .18s)}
.chv-hotcell.chv-hot-steady{animation:chvBreath var(--t-breath) var(--ease-breath) infinite}
@keyframes chvHotWave{0%,100%{opacity:.55}30%{opacity:1}}
body.rm .chv-weavecell,body.rm .chv-hotcell,body.quiet .chv-weavecell,body.quiet .chv-hotcell{animation:none}
body.rm .chv-hotcell,body.quiet .chv-hotcell{opacity:1}
@media (prefers-reduced-motion:reduce){.chv-weavecell,.chv-hotcell{animation:none}.chv-hotcell{opacity:1}}
