.chv-ov-row.chv-ov-hero::before{content:'';position:absolute;inset:0;pointer-events:none;border-radius:var(--r-s);
 background:radial-gradient(closest-side,color-mix(in srgb,var(--mk-top,var(--accent)) 14%,transparent),transparent)}
