.chv-row{display:flex;align-items:center;gap:10px;width:100%;min-height:var(--tap);padding:4px 0;
 background:transparent;border:0;border-top:1px solid var(--edge);color:var(--ink);font:inherit;
 font-size:13px;text-align:left;cursor:pointer}
